import java.math.BigDecimal
import java.math.RoundingMode
import java.util.NoSuchElementException

class Ledger {
    private val balances = HashMap<String, BigDecimal>()
    private val log = HashMap<String, MutableList<BigDecimal>>()

    fun openAccount(id: String, initial: BigDecimal = BigDecimal.ZERO) {
        if (balances.containsKey(id)) {
            throw IllegalArgumentException("Account $id already exists")
        }
        // Validate that initial is positive or zero? The spec says "Amounts must be positive" but initial can be ZERO.
        // Let's assume initial >= 0. Also validate scale.
        require(initial.scale() <= 2) { "Initial amount must have at most 2 decimal places" }
        if (initial < BigDecimal.ZERO) {
            throw IllegalArgumentException("Initial amount must be non-negative")
        }
        balances[id] = initial.setScale(2, RoundingMode.HALF_UP)
        log[id] = mutableListOf()
    }

    fun balance(id: String): BigDecimal {
        return balances[id] ?: throw NoSuchElementException("Account $id not found")
    }

    fun transfer(from: String, to: String, amount: BigDecimal) {
        require(amount > BigDecimal.ZERO) { "Transfer amount must be positive" }
        require(amount.scale() <= 2) { "Transfer amount must have at most 2 decimal places" }

        val fromBalance = balances[from] ?: throw NoSuchElementException("Account $from not found")
        val toBalance = balances[to] ?: throw NoSuchElementException("Account $to not found")

        // Check if transfer would overdraw
        if (fromBalance < amount) {
            throw IllegalStateException("insufficient funds")
        }

        val newFromBalance = fromBalance - amount
        val newToBalance = toBalance + amount

        balances[from] = newFromBalance
        balances[to] = newToBalance

        log.getValue(from).add(-amount)
        log.getValue(to).add(amount)
    }

    fun history(id: String): List<BigDecimal> {
        return log.getValue(id)
    }

    companion object {
        fun split(total: BigDecimal, n: Int): List<BigDecimal> {
            require(n > 0) { "Number of parts must be positive" }
            require(total >= BigDecimal.ZERO) { "Total must be non-negative" }

            // Divide total by n, rounding down to 2 decimal places for the base part
            val part = total.divide(BigDecimal(n), 2, RoundingMode.DOWN)
            val remainder = total - (part * n)

            val result = mutableListOf<BigDecimal>()
            for (i in 0 until n) {
                if (remainder > BigDecimal.ZERO) {
                    // Add one cent to the first parts that absorb the remainder
                    // Since we want larger parts first, we add the cent to the earlier parts
                    result.add(part + BigDecimal("0.01"))
                    remainder -= BigDecimal("0.01")
                } else {
                    result.add(part)
                }
            }
            return result
        }
    }
}
