```kotlin
fun toJson(value: Any?, indent: Int = 0): String {
    return buildString {
        appendValue(value, indent, 0)
    }
}

private fun StringBuilder.appendValue(value: Any?, indent: Int, level: Int) {
    when (value) {
        null -> append("null")
        is Boolean -> append(if (value) "true" else "false")
        is String -> appendString(value)
        is Int -> append(value.toString())
        is Long -> append(value.toString())
        is Double -> appendDouble(value)
        is Float -> appendDouble(value.toDouble())
        is Map<*, *> -> appendMap(value, indent, level)
        is List<*> -> appendList(value, indent, level)
        is Array<*> -> appendList(value.toList(), indent, level)
        is Enum<*> -> appendString(value.name)
        else -> throw IllegalArgumentException("Unsupported type: ${value::class.java}")
    }
}

private fun StringBuilder.appendString(value: String) {
    append('"')
    for (i in value.indices) {
        val c = value[i]
        when (c) {
            '"' -> append("\\\"")
            '\\' -> append("\\\\")
            '\b' -> append("\\b")
            '\f' -> append("\\f")
            '\n' -> append("\\n")
            '\r' -> append("\\r")
            '\t' -> append("\\t")
            else -> {
                val code = c.code
                if (code < 0x20) {
                    append("\\u%04x".format(code))
                } else {
                    append(c)
                }
            }
        }
    }
    append('"')
}

private fun StringBuilder.appendDouble(value: Double) {
    if (value.isNaN() || value.isInfinite()) {
        throw IllegalArgumentException("Non-finite double value")
    }
    // Use Kotlin's toString() for doubles as specified
    append(value.toString())
}

private fun StringBuilder.appendMap(value: Map<*, *>, indent: Int, level: Int) {
    val entries = value.entries.toList()
    if (entries.isEmpty()) {
        if (indent > 0) {
            append("{}")
        } else {
            append("{}")
        }
        return
    }

    // Validate keys are Strings
    for (entry in entries) {
        val key = entry.key
        if (key !is String) {
            throw IllegalArgumentException("Map keys must be Strings, got ${key::class.java}")
        }
    }

    if (indent > 0) {
        append("{\n")
        for ((index, entry) in entries.withIndex()) {
            val key = entry.key as String
            val v = entry.value
            val currentIndent = " ".repeat((level + 1) * indent)
            val nextIndent = " ".repeat((level + 2) * indent)
            append(currentIndent)
            appendString(key)
            append(": ")
            appendValue(v, indent, level + 1)
            if (index < entries.size - 1) {
                append(",")
            }
            append("\n")
        }
        append(" ".repeat(level * indent))
        append("}")
    } else {
        append("{")
        for ((index, entry) in entries.withIndex()) {
            val key = entry.key as String
            val v = entry.value
            appendString(key)
            append(":")
            appendValue(v, indent, level + 1)
            if (index < entries.size - 1) {
                append(",")
            }
        }
        append("}")
    }
}

private fun StringBuilder.appendList(value: List<*>, indent: Int, level: Int) {
    if (value.isEmpty()) {
        if (indent > 0) {
            append("[]")
        } else {
            append("[]")
        }
        return
    }

    if (indent > 0) {
        append("[\n")
        for ((index, v) in value.withIndex()) {
            val currentIndent = " ".repeat((level + 1) * indent)
            append(currentIndent)
            appendValue(v, indent, level + 1)
            if (index < value.size - 1) {
                append(",")
            }
            append("\n")
        }
        append(" ".repeat(level * indent))
        append("]")
    } else {
        append("[")
        for ((index, v) in value.withIndex()) {
            appendValue(v, indent, level + 1)
            if (index < value.size - 1) {
                append(",")
            }
        }
        append("]")
    }
}
