```kotlin
sealed class Token {
    abstract val pos: Int  // 0-based index of the token's first character
    data class Ident(val name: String, override val pos: Int) : Token()
    data class Str(val value: String, override val pos: Int) : Token()
    data class Num(val value: Double, override val pos: Int) : Token()
    data class Op(val symbol: String, override val pos: Int) : Token()
    data class Paren(val open: Boolean, override val pos: Int) : Token()
}

class TokenizeException(message: String, val pos: Int) : Exception(message)

fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0
    val len = input.length

    // Helper to check if the previous token allows a leading minus for a number
    fun canHaveLeadingMinus(): Boolean {
        return tokens.isEmpty() || 
               (tokens.last() is Token.Op) || 
               (tokens.last() is Token.Paren && tokens.last().open)
    }

    while (i < len) {
        val c = input[i]

        // Skip whitespace
        if (c == ' ' || c == '\t' || c == '\n') {
            i++
            continue
        }

        val startPos = i

        // Check for identifiers, numbers, or operators starting with specific chars
        if (c.isLetter() || c == '_') {
            // Identifier: [A-Za-z_][A-Za-z0-9_.]*
            var j = i + 1
            while (j < len) {
                val ch = input[j]
                if (ch.isLetterOrDigit() || ch == '_' || ch == '.') {
                    j++
                } else {
                    break
                }
            }
            // Check for invalid patterns like starting with dot or consecutive dots? 
            // The spec says [A-Za-z_][A-Za-z0-9_.]* so it's straightforward.
            val name = input.substring(i, j)
            tokens.add(Token.Ident(name, startPos))
            i = j
        } else if (c.isDigit()) {
            // Number: digits with optional fraction
            var j = i + 1
            var hasDot = false

            while (j < len && input[j].isDigit()) {
                j++
            }

            if (j < len && input[j] == '.') {
                // Check for "5." error case or ".5" (already handled by starting with digit)
                val nextJ = j + 1
                if (nextJ < len && input[nextJ].isDigit()) {
                    hasDot = true
                    j = nextJ
                    while (j < len && input[j].isDigit()) {
                        j++
                    }
                } else {
                    // It's "5." which is an error according to spec: ".5 and 5. are errors"
                    throw TokenizeException("Invalid number format", startPos)
                }
            }

            val numStr = input.substring(i, j)
            try {
                val value = numStr.toDouble()
                tokens.add(Token.Num(value, startPos))
            } catch (e: NumberFormatException) {
                throw TokenizeException("Invalid number format", startPos)
            }
            i = j
        } else if (c == '-' && canHaveLeadingMinus()) {
            // Potential negative number
            if (i + 1 < len && input[i + 1].isDigit()) {
                var j = i + 2
                var hasDot = false

                while (j < len && input[j].isDigit()) {
                    j++
                }

                if (j < len && input[j] == '.') {
                    val nextJ = j + 1
                    if (nextJ < len && input[nextJ].isDigit()) {
                        hasDot = true
                        j = nextJ
                        while (j < len && input[j].isDigit()) {
                            j++
                        }
                    } else {
                        throw TokenizeException("Invalid number format", startPos)
                    }
                }

                val numStr = input.substring(i, j)
                try {
                    val value = numStr.toDouble()
                    tokens.add(Token.Num(value, startPos))
                } catch (e: NumberFormatException) {
                    throw TokenizeException("Invalid number format", startPos)
                }
                i = j
            } else {
                // Just a minus sign, treat as operator? 
                // Spec says "A - elsewhere is an error". 
                // If it's not followed by a digit, and canHaveLeadingMinus is true, 
                // it might be intended as part of a number but malformed.
                // However, standard interpretation: if '-' is not followed by digit, it's an operator or error.
                // Given "A - elsewhere is an error", let's treat standalone '-' as error unless it's clearly an op?
                // But '-' is not in the operator list `== != <= >= < > && || !`.
                // So '-' alone is an error.
                throw TokenizeException("Unexpected character '-'", startPos)
            }
        } else if (c == '"' || c == '\'') {
            // String
            val quoteChar = c
            var j = i + 1
            val sb = StringBuilder()

            while (j < len) {
                val ch = input[j]
                if (ch == '\\') {
                    if (j + 1 >= len) {
                        throw TokenizeException("Unterminated string", startPos)
                    }
                    val nextCh = input[j + 1]
                    when (nextCh) {
                        'n' -> sb.append('\n')
                        '\\' -> sb.append('\\')
                        '\'' -> sb.append('\'')
                        '"' -> sb.append('"')
                        else -> sb.append(nextCh)
                    }
                    j += 2
                } else if (ch == quoteChar) {
                    break
                } else {
                    sb.append(ch)
                    j++
                }
            }

            if (j >= len || input[j] != quoteChar) {
                throw TokenizeException("Unterminated string", startPos)
            }

            // Consume the closing quote
            j++
            tokens.add(Token.Str(sb.toString(), startPos))
            i = j
        } else if (c == '(') {
            tokens.add(Token.Paren(true, startPos))
            i++
        } else if (c == ')') {
            tokens.add(Token.Paren(false, startPos))
            i++
        } else {
            // Try to match operators (longest match first)
            val possibleOps = listOf("==", "!=", "<=", ">=", "<", ">", "&&", "||", "!")
            var matchedOp: Token.Op? = null

            for (op in possibleOps) {
                if (input.startsWith(op, i)) {
                    // Check that we don't match a longer operator if applicable? 
                    // The list is ordered by length descending usually, but let's be careful.
                    // "==" vs "=" (not an op), "<=" vs "<".
                    // Since we iterate from longest to shortest in the list above, first match is longest.
                    matchedOp = Token.Op(op, startPos)
                    break
                }
            }

            if (matchedOp != null) {
                tokens.add(matchedOp)
                i += matchedOp.symbol.length
            } else {
                throw TokenizeException("Unexpected character '$c'", startPos)
            }
        }
    }

    return tokens
}
