            if (i + 1 < len && input[i + 1].isDigit()) {
                var j = i + 2
                var hasDot = false

                while (j < len && input[j].isDigit()) {
                    j++
                }

                if (j < len && input[j] == '.') {
                    val nextJ = j + 1
                    if (nextJ < len && input[nextJ].isDigit()) {
                        hasDot = true
                        j = nextJ
                        while (j < len && input[j].isDigit()) {
                            j++
                        }
                    } else {
                        throw TokenizeException("Invalid number format", startPos)
                    }
                }

                val numStr = input.substring(i, j)
                try {
                    val value = numStr.toDouble()
                    tokens.add(Token.Num(value, startPos))
                } catch (e: NumberFormatException) {
                    throw TokenizeException("Invalid number format", startPos)
                }
                i = j
            } else {
                // Just a minus sign, treat as operator? 
                // Spec says "A - elsewhere is an error". 
                // If it's not followed by a digit, and canHaveLeadingMinus is true, 
                // it might be intended as part of a number but malformed.
                // However, standard interpretation: if '-' is not followed by digit, it's an operator or error.
                // Given "A - elsewhere is an error", let's treat standalone '-' as error unless it's clearly an op?
                // But '-' is not in the operator list `== != <= >= < > && || !`.
                // So '-' alone is an error.
                throw TokenizeException("Unexpected character '-'", startPos)
            }
        } else if (c == '"' || c == '\'') {
            // String
            val quoteChar = c
            var j = i + 1
            val sb = StringBuilder()

            while (j < len) {
                val ch = input[j]
                if (ch == '\\') {
                    if (j + 1 >= len) {
                        throw TokenizeException("Unterminated string", startPos)
                    }
                    val nextCh = input[j + 1]
                    when (nextCh) {
                        'n' -> sb.append('\n')
                        '\\' -> sb.append('\\')
                        '\'' -> sb.append('\'')
                        '"' -> sb.append('"')
                        else -> sb.append(nextCh)
                    }
                    j += 2
                } else if (ch == quoteChar) {
                    break
                } else {
                    sb.append(ch)
                    j++
                }
            }

            if (j >= len || input[j] != quoteChar) {
                throw TokenizeException("Unterminated string", startPos)
            }

            // Consume the closing quote
            j++
            tokens.add(Token.Str(sb.toString(), startPos))
            i = j
        } else if (c == '(') {
            tokens.add(Token.Paren(true, startPos))
            i++
        } else if (c == ')') {
            tokens.add(Token.Paren(false, startPos))
            i++
        } else {
            // Try to match operators (longest match first)
            val possibleOps = listOf("==", "!=", "<=", ">=", "<", ">", "&&", "||", "!")
            var matchedOp: Token.Op? = null

            for (op in possibleOps) {
                if (input.startsWith(op, i)) {
                    // Check that we don't match a longer operator if applicable? 
                    // The list is ordered by length descending usually, but let's be careful.
                    // "==" vs "=" (not an op), "<=" vs "<".
                    // Since we iterate from longest to shortest in the list above, first match is longest.
                    matchedOp = Token.Op(op, startPos)
                    break
                }
            }

            if (matchedOp != null) {
                tokens.add(matchedOp)
                i += matchedOp.symbol.length
            } else {
                throw TokenizeException("Unexpected character '$c'", startPos)
            }
        }
    }

    return tokens
}
