def _parse_field(field_str: str, min_val: int, max_val: int, name_map: dict = None) -> list:
    """
    Parse a single cron field string and return a sorted list of valid integers in [min_val, max_val].
    Raises ValueError on invalid input.
    """
    if name_map is None:
        name_map = {}

    result = set()
    parts = field_str.split(',')
    for part in parts:
        # Handle step
        if '/' in part:
            range_part, step_str = part.split('/', 1)
            try:
                step = int(step_str)
            except ValueError:
                raise ValueError(f"Invalid step value: {step_str}")
            if step <= 0:
                raise ValueError(f"Step must be positive, got {step}")
        else:
            range_part = part
            step = None

        # Parse the range part
        if range_part == '*':
            start = min_val
            end = max_val
        elif '-' in range_part:
            sub_parts = range_part.split('-', 1)
            try:
                start_str = sub_parts[0]
                end_str = sub_parts[1]
                start = _resolve_name(start_str, name_map, min_val, max_val)
                end = _resolve_name(end_str, name_map, min_val, max_val)
            except (KeyError, ValueError) as e:
                if isinstance(e, KeyError):
                    raise ValueError(f"Unknown name in range: {e}")
                raise
            if start < min_val or start > max_val:
                raise ValueError(f"Value {start} out of range [{min_val}, {max_val}]")
            if end < min_val or end > max_val:
                raise ValueError(f"Value {end} out of range [{min_val}, {max_val}]")
            if start > end:
                raise ValueError(f"Range start {start} is greater than end {end}")
        else:
            try:
                val = _resolve_name(range_part, name_map, min_val, max_val)
            except KeyError:
                raise ValueError(f"Unknown value: {range_part}")
            if val < min_val or val > max_val:
                raise ValueError(f"Value {val} out of range [{min_val}, {max_val}]")
            if step is not None:
                # A/S means from A to max with step S
                start = val
                end = max_val
            else:
                result.add(val)
                continue

        # Generate values with step
        current = start
        while current <= end:
            result.add(current)
            current += step

    return sorted(result)


def _resolve_name(value_str: str, name_map: dict, min_val: int, max_val: int) -> int:
    """Resolve a numeric string or named value to an integer."""
    try:
        return int(value_str)
    except ValueError:
        pass
    # Try case-insensitive lookup in name map
    upper = value_str.upper()
    if upper in name_map:
        val = name_map[upper]
        if val < min_val or val > max_val:
            raise ValueError(f"Name '{value_str}' maps to {val}, out of range [{min_val}, {max_val}]")
        return val
    raise ValueError(f"Unknown name: {value_str}")


def next_fire(expr: str, after: datetime) -> datetime:
    """
    Compute the next fire time for a 5-field cron expression strictly after `after`.

    Args:
        expr: A standard 5-field cron expression.
        after: A naive datetime. The result will be strictly after this.

    Returns:
        The earliest datetime strictly after `after` that matches the cron expression.

    Raises:
        ValueError: If the expression is invalid or no match is found within 5 years.
    """
    fields = expr.strip().split()
    if len(fields) != 5:
        raise ValueError(f"Expected 5 fields, got {len(fields)}")

    # Name maps
    month_names = {}
    for i, name in enumerate(['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'], 1):
        month_names[name] = i

    day_names = {}
    for i, name in enumerate(['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'], 0):
        day_names[name] = i

    try:
        minutes = _parse_field(fields[0], 0, 59)
        hours = _parse_field(fields[1], 0, 23)
        days_of_month = _parse_field(fields[2], 1, 31)
        months = _parse_field(fields[3], 1, 12, month_names)
        days_of_week = _parse_field(fields[4], 0, 7, day_names)
    except ValueError as e:
        raise

    # Check if day-of-month and day-of-week are restricted (not just *)
    dom_restricted = fields[2].strip() != '*'
    dow_restricted = fields[4].strip() != '*'

    # Normalize days_of_week: 7 -> 0 (both represent Sunday)
    normalized_dow = set()
    for d in days_of_week:
        if d == 7:
            normalized_dow.add(0)
        else:
            normalized_dow.add(d)
    sorted_dow = sorted(normalized_dow)

    # Start searching from the next minute after `after`
    candidate = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    # We'll search for up to 5 years
    end_time = after + timedelta(days=365 * 5 + 1)  # Account for leap years roughly

    # Optimization: jump by months/years when possible, but simple iteration is safer for correctness
    # Given the constraint of 5 years max, we can iterate day by day or minute by minute.
    # Iterating minute by minute could be up to 5*365*24*60 ~ 2.6 million iterations which is acceptable in Python.

    current = candidate

    while current < end_time:
        year = current.year
        month = current.month
        day = current.day
        hour = current.hour
        minute = current.minute

        # Check month
        if month not in months:
            # Jump to the next valid month
            # Find the next valid month in the same year or next year
            found_next_month = False
            for m in months:
                if m > month:
                    # Try to set to this month, day 1, hour 0, minute first valid minute
                    try:
                        new_date = datetime(year, m, 1, 0, 0)
                        current = _find_next_valid_in_month(new_date, minutes, hours, days_of_month, months, sorted_dow, dom_restricted, dow_restricted)
                        if current is not None and current >= end_time:
                            raise ValueError("No match found within 5 years")
                        break
                    except ValueError:
                        continue
            else:
                # No valid month left in this year, go to next year
                try:
                    new_date = datetime(year + 1, months[0], 1, 0, 0)
                    current = _find_next_valid_in_month(new_date, minutes, hours, days_of_month, months, sorted_dow, dom_restricted, dow_restricted)
                    if current is not None and current >= end_time:
                        raise ValueError("No match found within 5 years")
                except (ValueError, IndexError):
                    raise ValueError("No match found within 5 years")
            continue

        # Check day matching
        dow = current.weekday()
        # Python's weekday(): Monday=0, Sunday=6. Cron: Sunday=0 or 7, Monday=1, ..., Saturday=6
        cron_dow = (dow + 1) % 7  # Convert to cron day-of-week where Sunday=0

        dom_match = day in days_of_month
        dow_match = cron_dow in sorted_dow

        if dom_restricted and dow_restricted:
            day_match = dom_match or dow_match
        else:
            day_match = dom_match and dow_match

        if not day_match:
            # Jump to next day
            current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # Check hour
        if hour not in hours:
            # Find next valid hour in this day
            found_next_hour = False
            for h in hours:
                if h > hour:
                    current = current.replace(hour=h, minute=minutes[0])
                    found_next_hour = True
                    break
            if not found_next_hour:
                # No more valid hours today, go to next day
                current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # Check minute
        if minute not in minutes:
            # Find next valid minute in this hour
            found_next_minute = False
            for m in minutes:
                if m > minute:
                    current = current.replace(minute=m)
                    found_next_minute = True
                    break
            if not found_next_minute:
                # No more valid minutes this hour, go to next hour
                current = (current + timedelta(hours=1)).replace(minute=0)
            continue

        # All fields match
        return current

    raise ValueError("No match found within 5 years")


def _find_next_valid_in_month(start_date: datetime, minutes: list, hours: list, days_of_month: list, months: list, sorted_dow: list, dom_restricted: bool, dow_restricted: bool) -> datetime:
    """
    Find the next valid datetime starting from start_date (which should be at day 1, hour 0, minute 0 of a valid month).
    This helper is used to jump efficiently.
    """
    current = start_date

    # We'll iterate through days in this month until we find a match or run out of days
    # Get the last day of the month
    year = current.year
    month = current.month
    _, last_day = calendar.monthrange(year, month)

    while current.day <= last_day:
        day = current.day
        hour = current.hour
        minute = current.minute

        # Check day matching for this specific date
        dow = current.weekday()
        cron_dow = (dow + 1) % 7

        dom_match = day in days_of_month
        dow_match = cron_dow in sorted_dow

        if dom_restricted and dow_restricted:
            day_match = dom_match or dow_match
        else:
            day_match = dom_match and dow_match

        if not day_match:
            # Move to next day
            current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # Check hour
        if hour not in hours:
            found_next_hour = False
            for h in hours:
                if h > hour:
                    current = current.replace(hour=h, minute=minutes[0])
                    found_next_hour = True
                    break
            if not found_next_hour:
                # No more valid hours today, go to next day
                current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # Check minute
        if minute not in minutes:
            found_next_minute = False
            for m in minutes:
                if m > minute:
                    current = current.replace(minute=m)
                    found_next_minute = True
                    break
            if not found_next_minute:
                # No more valid minutes this hour, go to next hour
                current = (current + timedelta(hours=1)).replace(minute=0)
            continue

        # All fields match
        return current

    # If we exhaust the month, raise ValueError or signal no match in this month
    raise ValueError("No match found in this month")
