def merge(base: dict, *overrides: dict) -> dict:
    """
    Deep merge configuration layers where later overrides win.

    - Dicts are merged recursively.
    - Any other value in an override replaces the base value (lists are replaced, not concatenated).
    - A key whose override value is None deletes that key from the result.
    - A key ending in '+' appends: {"plugins+": ["x"]} appends the items to the base list `plugins`.
      If the base value exists and is not a list, raise TypeError. The '+' key itself never appears in the result.
    - Inputs must not be mutated, and the result must not share mutable dicts/lists with the inputs (a deep copy).
    """
    import copy

    def deep_copy(obj):
        return copy.deepcopy(obj)

    def merge_dicts(base_dict, override_dict):
        """Merge override_dict into base_dict recursively."""
        # Start with a deep copy of base_dict to avoid mutation and sharing
        result = deep_copy(base_dict)

        for key, value in override_dict.items():
            if key.endswith('+'):
                # Handle append operation
                list_key = key[:-1]  # Remove the '+' suffix

                if value is None:
                    # If override value is None, delete the key from result
                    if list_key in result:
                        del result[list_key]
                    continue

                # Check if the base has this key
                if list_key not in result:
                    # No base value, so create a new list with the appended items
                    # But wait - the override is for appending. If there's no base, 
                    # we should just use the override value as a new list? 
                    # Actually, "appends the items to the base list (missing base -> new list)"
                    # So if base doesn't have it, create a new list from the override
                    result[list_key] = deep_copy(value)
                else:
                    # Base exists, must be a list
                    if not isinstance(result[list_key], list):
                        raise TypeError(
                            f"Key '{list_key}' in base is not a list, but append operation requested via key '{key}'"
                        )
                    # Append the override items to the existing list
                    result[list_key] = result[list_key] + deep_copy(value)
            else:
                if value is None:
                    # Delete the key from result
                    if key in result:
                        del result[key]
                elif isinstance(value, dict) and key in result and isinstance(result[key], dict):
                    # Recursively merge dicts
                    result[key] = merge_dicts(result[key], value)
                else:
                    # Replace the value (deep copy to avoid sharing)
                    result[key] = deep_copy(value)

        return result

    # Start with a deep copy of base
    if base is None:
        current = {}
    else:
        current = deep_copy(base)

    for override in overrides:
        if override is None:
            continue
        current = merge_dicts(current, override)

    return current
