def flatten(obj, sep=".") -> dict:
    """
    Turns nested dicts and lists into a flat dict with path keys.

    - Dict keys are joined with `sep`.
    - List items use their index (`a.0.b`).
    - Empty dicts and empty lists are kept as leaf values.
    - Any other value is a leaf.
    - The top-level object must be a dict (else TypeError).
    - Keys must be strings that don't contain `sep` (else ValueError).
    - Order: depth-first, in the input's order.
    """
    if not isinstance(obj, dict):
        raise TypeError("Top-level object must be a dict")

    # Validate top-level keys
    for key in obj.keys():
        if not isinstance(key, str):
            raise ValueError(f"Key must be a string, got {type(key)}")
        if sep in key:
            raise ValueError(f"Key '{key}' contains separator '{sep}'")

    result = {}

    def _flatten(current, prefix):
        if isinstance(current, dict):
            if len(current) == 0:
                # Empty dict is a leaf value
                result[prefix] = current
            else:
                for key in current.keys():
                    new_key = f"{prefix}{sep}{key}" if prefix else key
                    _flatten(current[key], new_key)
        elif isinstance(current, list):
            if len(current) == 0:
                # Empty list is a leaf value
                result[prefix] = current
            else:
                for i, item in enumerate(current):
                    new_key = f"{prefix}{sep}{i}" if prefix else str(i)
                    _flatten(item, new_key)
        else:
            # Any other value is a leaf
            result[prefix] = current

    _flatten(obj, "")

    return result


def unflatten(flat: dict, sep=".") -> dict:
    """
    Inverse of flatten: turns a flat dict with path keys back into nested dicts/lists.

    - A path segment that is a non-negative integer without leading zeros creates a list.
    - Lists must be dense: indices must be exactly 0..n-1 (else ValueError).
    - Conflicts such as {"a": 1, "a.b": 2} raise ValueError.
    """
    if not isinstance(flat, dict):
        raise TypeError("Input must be a dict")

    result = {}

    for path, value in flat.items():
        # Split the path into segments
        segments = _split_path(path, sep)

        # Navigate/create the nested structure
        _set_nested(result, segments, value)

    return result


def _split_path(path: str, sep: str) -> list:
    """Split a path string into segments by separator."""
    if not path:
        return []
    return path.split(sep)


def _is_valid_list_index(segment: str) -> bool:
    """Check if a segment is a valid non-negative integer without leading zeros."""
    if not segment:
        return False
    # Must be all digits
    if not segment.isdigit():
        return False
    # No leading zeros (except for "0" itself)
    if len(segment) > 1 and segment[0] == '0':
        return False
    return True


def _set_nested(root: dict, segments: list, value) -> None:
    """Set a value in the nested structure at the given path segments."""
    if not segments:
        # This shouldn't happen for valid inputs, but handle it
        raise ValueError("Empty path segment")

    current = root

    for i, seg in enumerate(segments[:-1]):
        last_segment = False
        is_list_index = _is_valid_list_index(seg)

        if is_list_index:
            idx = int(seg)
            # Current should be a list
            if not isinstance(current, list):
                raise ValueError(f"Expected list at segment '{seg}', got {type(current).__name__}")

            # Check bounds - we need to ensure the list has enough elements
            if idx >= len(current):
                raise ValueError(f"List index {idx} out of range for list of length {len(current)}")

            current = current[idx]
        else:
            # Current should be a dict
            if not isinstance(current, dict):
                raise ValueError(f"Expected dict at segment '{seg}', got {type(current).__name__}")

            next_seg = segments[i + 1]
            is_next_list_index = _is_valid_list_index(next_seg)

            if seg in current:
                # Check for conflict
                existing = current[seg]
                if isinstance(existing, dict) and is_next_list_index:
                    raise ValueError(f"Conflict: key '{seg}' exists as a value but should be a container")
                elif isinstance(existing, list) and not is_next_list_index:
                    raise ValueError(f"Conflict: key '{seg}' exists as a value but should be a container")
            else:
                # Determine what type to create for the next level
                if is_next_list_index:
                    current[seg] = []
                else:
                    current[seg] = {}

            current = current[seg]

    # Now handle the last segment
    last_seg = segments[-1]
    is_last_list_index = _is_valid_list_index(last_seg)

    if is_last_list_index:
        idx = int(last_seg)
        if not isinstance(current, list):
            raise ValueError(f"Expected list at segment '{last_seg}', got {type(current).__name__}")

        # Check for conflict or out of range
        if idx < len(current):
            # Index already exists - this is a conflict
            raise ValueError(f"Conflict: index {idx} already exists in list")
        elif idx == len(current):
            current.append(value)
        else:
            # Gap in indices
            raise ValueError(f"List index {idx} out of range for list of length {len(current)} (indices must be 0..{len(current)-1})")
    else:
        if not isinstance(current, dict):
            raise ValueError(f"Expected dict at segment '{last_seg}', got {type(current).__name__}")

        if last_seg in current:
            raise ValueError(f"Conflict: key '{last_seg}' already exists")

        current[last_seg] = value
