import math

def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    if env is None:
        env = {}

    # Tokenizer
    tokens = []
    i = 0
    s = expr

    while i < len(s):
        c = s[i]

        # Skip whitespace
        if c.isspace():
            i += 1
            continue

        # Numbers
        if c.isdigit() or (c == '.' and i + 1 < len(s) and s[i+1].isdigit()):
            start = i
            has_dot = False
            while i < len(s) and (s[i].isdigit() or s[i] == '.'):
                if s[i] == '.':
                    if has_dot:
                        break # Error? Or just stop? Grammar says decimal literals. Usually one dot.
                    has_dot = True
                i += 1

            num_str = s[start:i]
            if '.' in num_str:
                tokens.append(('NUMBER', float(num_str)))
            else:
                tokens.append(('NUMBER', int(num_str)))
            continue

        # Identifiers and Functions
        if c.isalpha() or c == '_':
            start = i
            while i < len(s) and (s[i].isalnum() or s[i] == '_'):
                i += 1

            word = s[start:i]
            tokens.append(('IDENT', word))
            continue

        # Operators and Punctuation
        if c in '?':
            tokens.append(('?', '?'))
            i += 1
            continue

        if c in ':()!':
            tokens.append((c, c))
            i += 1
            continue

        # Two-char operators
        if i + 1 < len(s):
            two = s[i:i+2]
            if two == '||' or two == '&&' or two == '==' or two == '!=' or two == '<=' or two == '>=':
                tokens.append((two, two))
                i += 2
                continue

        # Single char operators
        if c in '+-*/%^<>':
            tokens.append((c, c))
            i += 1
            continue

        raise SyntaxError(f"Unexpected character '{c}'")

    # Parser State
    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return None

    def consume(expected_type=None, expected_val=None):
        nonlocal pos
        token = peek()
        if token is None:
            raise SyntaxError("Unexpected end of input")

        ttype, tval = token

        if expected_type and ttype != expected_type:
            raise SyntaxError(f"Expected {expected_type}, got {ttype} ({tval})")
        if expected_val and tval != expected_val:
            raise SyntaxError(f"Expected '{expected_val}', got '{tval}'")

        pos += 1
        return token

    def current_token():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return None

    # --- Parser Functions ---

    def parse_atom():
        """Parse atoms: literals, identifiers, function calls, parentheses."""
        token = peek()
        if token is None:
            raise SyntaxError("Unexpected end of input in atom")

        ttype, tval = token

        # Literal Number
        if ttype == 'NUMBER':
            consume()
            return tval

        # Identifier / Function Call
        if ttype == 'IDENT':
            name = tval
            consume()

            # Check for function call
            next_tok = peek()
            if next_tok and next_tok[0] == '(':
                consume('(') # Consume '('

                args = []
                if peek() and peek()[0] != ')':
                    while True:
                        val = parse_conditional()
                        args.append(val)
                        next_p = peek()
                        if next_p and next_p[0] == ',':
                            consume(',')
                        elif next_p and next_p[0] == ')':
                            break
                        else:
                            raise SyntaxError("Expected ',' or ')' in function call")

                consume(')') # Consume ')'

                if name == 'min':
                    if not args:
                        raise ValueError("min() requires at least 1 argument")
                    return min(args)
                elif name == 'max':
                    if not args:
                        raise ValueError("max() requires at least 1 argument")
                    return max(args)
                elif name == 'abs':
                    if len(args) != 1:
                        raise SyntaxError("abs() requires exactly 1 argument")
                    return abs(args[0])
                else:
                    raise NameError(f"Unknown function '{name}'")
            else:
                # Variable lookup
                if name not in env:
                    raise NameError(f"Undefined variable '{name}'")
                return float(env[name])

        # Parenthesized Expression
        if ttype == '(':
            consume('(')
            val = parse_conditional()
            consume(')')
            return val

        raise SyntaxError(f"Unexpected token in atom: {tval}")

    def parse_power():
        """Parse Power (^) and Atoms. Right-associative."""
        # LHS is an atom (or parenthesized expr handled by atom)
        lhs = parse_atom()

        while peek() and peek()[0] == '^':
            consume('^')
            # RHS is a unary expression because ^ binds tighter than unary?
            # No, based on our trace, RHS of ^ can be unary.
            rhs = parse_unary()
            lhs = lhs ** rhs

        return lhs

    def parse_unary():
        """Parse Unary operators (-, +, !)."""
        token = peek()

        if token is None:
            raise SyntaxError("Unexpected end of input in unary")

        ttype, tval = token

        if ttype == '-':
            consume('-')
            return -parse_power()
        elif ttype == '+':
            consume('+')
            return parse_power()
        elif ttype == '!':
            consume('!')
            val = parse_power()
            return 1.0 if val == 0 else 0.0

        # If not a unary operator, fall through to power (which calls atom)
        return parse_power()

    def parse_mul_div_mod():
        """Parse *, /, %. Left-associative."""
        lhs = parse_unary()

        while peek() and peek()[0] in ('*', '/', '%'):
            op = consume()[1]
            rhs = parse_unary()

            if op == '*':
                lhs = lhs * rhs
            elif op == '/':
                if rhs == 0:
                    raise ZeroDivisionError("Division by zero")
                # Int division if both ints and exact
                if isinstance(lhs, int) and isinstance(rhs, int) and (lhs % rhs == 0):
                    lhs = lhs // rhs
                else:
                    lhs = lhs / rhs
            elif op == '%':
                if rhs == 0:
                    raise ZeroDivisionError("Modulo by zero")
                # Python semantics for modulo with floats? 
                # Prompt says "% follows Python semantics".
                # In Python, -1 % 2 is 1.
                lhs = lhs % rhs

        return lhs

    def parse_add_sub():
        """Parse +, -. Left-associative."""
        lhs = parse_mul_div_mod()

        while peek() and peek()[0] in ('+', '-'):
            op = consume()[1]
            rhs = parse_mul_div_mod()

            if op == '+':
                lhs = lhs + rhs
            elif op == '-':
                lhs = lhs - rhs

        return lhs

    def parse_comparison():
        """Parse comparisons. Non-associative."""
        lhs = parse_add_sub()

        token = peek()
        if token is None:
            return lhs

        ttype, tval = token

        if ttype in ('==', '!=', '<', '<=', '>', '>='):
            consume()
            rhs = parse_add_sub()

            # Check for chained comparison (non-associative error)
            # If we just parsed a comparison, the next token shouldn't be a comparison operator
            # unless it's part of a different expression? No, grammar says non-associative.
            # So 1 < 2 < 3 is an error.
            # Our parser structure: parse_comparison calls parse_add_sub for RHS.
            # If the RHS starts with a number, fine.
            # But what if the input is `1 < 2 < 3`?
            # parse_comparison:
            #   lhs = 1
            #   sees <. consume.
            #   rhs = parse_add_sub() -> returns 2.
            #   result 1.
            #   loop ends because next token is <, but we are back in the caller?
            #   Wait, parse_comparison only does ONE comparison.
            #   The caller (parse_logical_and) will see the next token '<' and fail?
            #   No, parse_logical_and expects logical operators or end.
            #   So if we have `1 < 2 < 3`, after parsing `1 < 2`, we return to `parse_logical_and`.
            #   `parse_logical_and` sees `<`. It is not a logical operator.
            #   So it will raise SyntaxError? Or try to parse it as something else?
            #   The top level call is parse_conditional.
            #   If parse_conditional returns 1, and there are more tokens (`< 3`), 
            #   we need to check for trailing tokens.

            if tval == '==':
                return 1.0 if lhs == rhs else 0.0
            elif tval == '!=':
                return 1.0 if lhs != rhs else 0.0
            elif tval == '<':
                return 1.0 if lhs < rhs else 0.0
            elif tval == '<=':
                return 1.0 if lhs <= rhs else 0.0
            elif tval == '>':
                return 1.0 if lhs > rhs else 0.0
            elif tval == '>=':
                return 1.0 if lhs >= rhs else 0.0

        return lhs

    def parse_logical_and():
        """Parse &&."""
        lhs = parse_comparison()

        while peek() and peek()[0] == '&&':
            consume('&&')
            # Short-circuit: only evaluate RHS if LHS is true (non-zero)
            if lhs == 0:
                # Consume the rest? No, we need to parse it to detect syntax errors?
                # Or just return 0?
                # "Only the chosen branch is evaluated" applies to conditional.
                # For logical operators, short-circuit usually means don't evaluate RHS side effects.
                # But here we just have values.
                # If we don't parse RHS, we might miss syntax errors in RHS?
                # Usually, parsers parse the whole tree but only compute if needed.
                # However, for simplicity and since there are no side effects, 
                # we can just return 0. But we must consume tokens?
                # No, we can't consume tokens we don't parse.
                # Let's parse RHS anyway to ensure syntax is valid, but use the short-circuit value.
                rhs = parse_comparison()
                lhs = 0
            else:
                rhs = parse_comparison()
                if rhs == 0:
                    lhs = 0
                else:
                    lhs = 1 # Result is 1 or 0

        return lhs

    def parse_logical_or():
        """Parse ||."""
        lhs = parse_logical_and()

        while peek() and peek()[0] == '||':
            consume('||')
            if lhs != 0:
                rhs = parse_comparison() # Parse to validate syntax?
                lhs = 1
            else:
                rhs = parse_comparison()
                if rhs != 0:
                    lhs = 1
                else:
                    lhs = 0

        return lhs

    def parse_conditional():
        """Parse a ? b : c. Right-associative."""
        # We need to handle right associativity: a ? b : c ? d : e -> a ? b : (c ? d : e)

        # Parse condition
        cond = parse_logical_or()

        token = peek()
        if token and token[0] == '?':
            consume('?')

            # Parse true branch
            true_val = parse_conditional()

            consume(':')

            # Parse false branch
            false_val = parse_conditional()

            if cond != 0:
                return true_val
            else:
                return false_val

        return cond

    # --- Main Execution ---

    result = parse_conditional()

    # Check for trailing tokens
    if pos < len(tokens):
        raise SyntaxError("Unexpected trailing tokens")

    return result
