def load_ini(text: str) -> dict[str, dict[str, str]]:
    """
    Parse an INI-like text into a dictionary of sections.

    Returns a dict mapping section names to dicts of key-value pairs.
    Keys are lowercased and trimmed; values are trimmed (unless quoted).
    """
    return _load_ini_impl(text)


def _parse_value(raw: str, line_num: int) -> tuple[str, int]:
    """
    Parse a value string (after the separator).
    Returns (parsed_value, length_consumed_from_raw).

    Handles:
    - Inline comments: ' ;' or ' #' (whitespace before marker) end the value, unless inside double quotes.
    - Quoted values: fully wrapped in double quotes -> remove quotes, keep inner whitespace, handle \".
    """
    if raw == '':
        return ('', 0)

    # Check if the value starts with a quote (after leading whitespace)
    stripped_raw = raw.lstrip()
    offset = len(raw) - len(stripped_raw)

    if stripped_raw.startswith('"'):
        # Quoted value
        # Find the closing quote, handling escaped quotes \"
        result = []
        j = 1  # skip opening quote
        closed = False
        while j < len(stripped_raw):
            ch = stripped_raw[j]
            if ch == '\\' and j + 1 < len(stripped_raw) and stripped_raw[j + 1] == '"':
                result.append('"')
                j += 2
            elif ch == '"':
                closed = True
                j += 1
                break
            else:
                result.append(ch)
                j += 1

        if not closed:
            raise ValueError(f"line {line_num}: unterminated quote")

        # After the closing quote, there might be inline comments or whitespace
        rest = stripped_raw[j:]
        # Inline comment: look for ' #' or ' ;' with at least one space before
        comment_pos = _find_inline_comment(rest)
        if comment_pos != -1:
            final_value = ''.join(result) + rest[:comment_pos]
        else:
            final_value = ''.join(result)

        return (final_value, offset + j + (comment_pos if comment_pos != -1 else len(rest)))
    else:
        # Unquoted value: look for inline comment
        comment_pos = _find_inline_comment(stripped_raw)
        if comment_pos != -1:
            value = stripped_raw[:comment_pos]
        else:
            value = stripped_raw

        return (value, offset + len(stripped_raw))


def _find_inline_comment(s: str) -> int:
    """
    Find the position of an inline comment in a string.
    Inline comments are ' #' or ' ;' preceded by at least one whitespace character.
    Returns the index of the space before # or ;, or -1 if no inline comment.
    """
    for i in range(1, len(s)):
        if s[i] == '#' or s[i] == ';':
            if s[i - 1] == ' ' or s[i - 1] == '\t':
                return i - 1
    return -1


def _load_ini_impl(text: str) -> dict[str, dict[str, str]]:
    lines = text.split('\n')

    sections: dict[str, dict[str, str]] = {}
    current_section: Optional[str] = None

    # Track last entry for continuation: (section_name, key, value_accumulated)
    last_entry_info: Optional[tuple[str, str, str]] = None

    i = 0
    while i < len(lines):
        line = lines[i]
        line_num = i + 1

        stripped = line.strip()

        # Blank line or comment ends any continuation
        if stripped == '' or stripped.startswith('#') or stripped.startswith(';'):
            last_entry_info = None
            i += 1
            continue

        # Section header
        if stripped.startswith('['):
            close_idx = stripped.find(']')
            if close_idx == -1:
                raise ValueError(f"line {line_num}: unclosed section header")
            section_name = stripped[1:close_idx].strip()
            current_section = section_name
            if current_section not in sections:
                sections[current_section] = {}
            last_entry_info = None
            i += 1
            continue

        # Entry line
        # Find separator (first unquoted '=' or ':')
        sep_pos = -1
        in_quotes = False
        for j, ch in enumerate(stripped):
            if ch == '"':
                in_quotes = not in_quotes
            elif not in_quotes and (ch == '=' or ch == ':'):
                sep_pos = j
                break

        if sep_pos == -1:
            raise ValueError(f"line {line_num}: missing separator")

        key = stripped[:sep_pos].strip().lower()
        raw_value = stripped[sep_pos + 1:]

        # Parse the value (handles quotes and inline comments)
        value, consumed = _parse_value(raw_value, line_num)

        sec_name = current_section if current_section is not None else ""
        last_entry_info = (sec_name, key, value)

        # Check for continuation lines
        i += 1
        while i < len(lines):
            next_line = lines[i]
            next_stripped = next_line.strip()

            # Blank line or comment ends continuation
            if next_stripped == '' or next_stripped.startswith('#') or next_stripped.startswith(';'):
                break

            # Continuation line must start with whitespace (but not be blank)
            if not (next_line and next_line[0] in (' ', '\t')):
                break

            # Parse the continuation line's value
            cont_value, _ = _parse_value(next_stripped, line_num + i)

            # Append with a single \n
            prev_section, prev_key, prev_val = last_entry_info
            last_entry_info = (prev_section, prev_key, prev_val + '\n' + cont_value)

            i += 1

        # Store the entry
        sec_name, k, v = last_entry_info
        if sec_name not in sections:
            sections[sec_name] = {}
        sections[sec_name][k] = v
        last_entry_info = None

    # Remove empty sections if they have no keys
    result = {}
    for sec_name, sec_dict in sections.items():
        if sec_dict:
            result[sec_name] = sec_dict

    # Handle interpolation
    _interpolate(result)

    return result


def _interpolate(sections: dict[str, dict[str, str]]) -> None:
    """
    Perform interpolation on all values.
    ${key} refers to a key in the same section.
    ${section:key} refers to another section.
    $$ is a literal $.
    Resolve recursively. Raise ValueError for undefined references or cycles.
    """

    def resolve(value: str, section: str, resolving_set: set[tuple[str, str]]) -> str:
        """Resolve interpolation in a value string."""
        result = []
        i = 0
        while i < len(value):
            if value[i] == '$':
                if i + 1 < len(value) and value[i + 1] == '$':
                    # Literal $
                    result.append('$')
                    i += 2
                elif i + 1 < len(value) and value[i + 1] == '{':
                    # Variable reference ${...}
                    close_idx = value.find('}', i + 2)
                    if close_idx == -1:
                        raise ValueError(f"Invalid interpolation syntax")
                    ref = value[i + 2:close_idx]

                    if ':' in ref:
                        parts = ref.split(':', 1)
                        ref_section = parts[0]
                        ref_key = parts[1]
                        if ref_section not in sections:
                            raise ValueError(f"Undefined section '{ref_section}' in reference")
                        if ref_key not in sections[ref_section]:
                            raise ValueError(f"Undefined key '{ref_key}' in section '{ref_section}'")

                        # Check for cycles
                        ref_entry = (ref_section, ref_key)
                        if ref_entry in resolving_set:
                            raise ValueError(f"Reference cycle detected involving {ref_entry}")

                        ref_value = sections[ref_section][ref_key]
                        new_resolving = resolving_set | {ref_entry}
                        resolved_ref = resolve(ref_value, ref_section, new_resolving)
                    else:
                        # Same section reference
                        if ref not in sections[section]:
                            raise ValueError(f"Undefined key '{ref}' in section '{section}'")

                        ref_entry = (section, ref)
                        if ref_entry in resolving_set:
                            raise ValueError(f"Reference cycle detected involving {ref_entry}")

                        ref_value = sections[section][ref]
                        new_resolving = resolving_set | {ref_entry}
                        resolved_ref = resolve(ref_value, section, new_resolving)

                    result.append(resolved_ref)
                    i = close_idx + 1
                else:
                    # Just a $ not followed by $ or {
                    result.append('$')
                    i += 1
            else:
                result.append(value[i])
                i += 1

        return ''.join(result)

    for section_name in list(sections.keys()):
        for key in list(sections[section_name].keys()):
            value = sections[section_name][key]
            resolved = resolve(value, section_name, {(section_name, key)})
            sections[section_name][key] = resolved
