import re
from typing import List, Optional, Tuple


class Version:
    """Represents a Semantic Version 2.0.0."""

    def __init__(self, major: int, minor: int, patch: int, prerelease: Optional[Tuple[str, ...]] = None, build: Optional[Tuple[str, ...]] = None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease  # tuple of strings/ints
        self.build = build

    def __repr__(self):
        s = f"Version({self.major}, {self.minor}, {self.patch}"
        if self.prerelease:
            s += f", prerelease={self.prerelease}"
        if self.build:
            s += f", build={self.build}"
        s += ")"
        return s

    def __str__(self):
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            s += "-" + ".".join(str(p) for p in self.prerelease)
        if self.build:
            s += "+" + ".".join(self.build)
        return s

    def _cmp_key(self):
        """Return a key for comparison following SemVer precedence rules."""
        # Build metadata is ignored for precedence
        pre = self.prerelease
        if pre is None:
            # Release versions have higher precedence than prerelease
            # We represent this by using a special marker that sorts after any prerelease identifier list
            return (self.major, self.minor, self.patch, 1, ())
        else:
            # For prerelease, we need to compare each identifier
            # Numeric identifiers are compared as integers, alphanumeric as strings
            # A shorter set is smaller if all preceding identifiers are equal
            def pre_key_item(item):
                if isinstance(item, int):
                    return (0, item, "")
                else:
                    return (1, 0, item)

            key_items = tuple(pre_key_item(p) for p in pre)
            return (self.major, self.minor, self.patch, 0, key_items)

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        # == follows precedence: build metadata ignored
        return self._cmp_key() == other._cmp_key()

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() < other._cmp_key()

    def __le__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() <= other._cmp_key()

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() > other._cmp_key()

    def __ge__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp_key() >= other._cmp_key()

    def __ne__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return not self.__eq__(other)


def parse(v: str) -> Version:
    """Parse a SemVer string into a Version object."""
    v = v.strip()
    if not v:
        raise ValueError(f"Invalid version: empty string")

    # Remove leading 'v' or '='
    if v.startswith('v') or v.startswith('='):
        v = v[1:]

    # Regex for SemVer 2.0.0
    # MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
    pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'

    match = re.match(pattern, v)
    if not match:
        raise ValueError(f"Invalid version string: {v}")

    major = int(match.group(1))
    minor = int(match.group(2))
    patch = int(match.group(3))

    prerelease_str = match.group(4)
    build_str = match.group(5)

    prerelease = None
    if prerelease_str:
        # Split by '.' and convert numeric identifiers to integers
        parts = prerelease_str.split('.')
        pre_list = []
        for part in parts:
            if not part:
                raise ValueError(f"Invalid prerelease identifier: empty")
            if re.match(r'^[0-9]+$', part):
                # Check for leading zeros - but the regex already ensures no leading zeros for pure numeric
                pre_list.append(int(part))
            else:
                if not re.match(r'^[0-9A-Za-z-]+$', part):
                    raise ValueError(f"Invalid prerelease identifier: {part}")
                pre_list.append(part)
        prerelease = tuple(pre_list)

    build = None
    if build_str:
        parts = build_str.split('.')
        for part in parts:
            if not part or not re.match(r'^[0-9A-Za-z-]+$', part):
                raise ValueError(f"Invalid build metadata identifier: {part}")
        build = tuple(parts)

    return Version(major, minor, patch, prerelease, build)


def _parse_partial_version(v_str: str) -> Version:
    """Parse a partial version string (e.g., '1', '1.2', '1.2.3') into a full Version."""
    v_str = v_str.strip()
    if not v_str:
        raise ValueError(f"Invalid partial version: empty")

    # Remove leading 'v' or '='
    if v_str.startswith('v') or v_str.startswith('='):
        v_str = v_str[1:]

    # Handle X ranges like 1.x, 1.2.*, etc.
    # We need to parse the numeric parts and treat X/x/* as wildcards for upper bound purposes
    # But for creating a base version, we fill in zeros.

    # Split by '.'
    parts = v_str.split('.')
    if len(parts) > 3:
        raise ValueError(f"Invalid partial version: {v_str}")

    nums = []
    for part in parts:
        part = part.strip()
        if part.lower() in ('x', '*', ''):
            # This is a wildcard - we'll handle it specially
            nums.append(None)
        else:
            try:
                n = int(part)
                if part and str(n) != part.lstrip('0') or (part.startswith('0') and len(part) > 1):
                    raise ValueError(f"Leading zeros in partial version part: {part}")
                nums.append(n)
            except ValueError:
                raise ValueError(f"Invalid partial version part: {part}")

    # Fill in missing parts with 0
    while len(nums) < 3:
        nums.append(0)

    major, minor, patch = nums[0], nums[1], nums[2]

    # Check for X/x/* in the original string to determine if it's a wildcard range
    # For now, just return the version with zeros filled in
    return Version(major, minor, patch)


def _is_x_range_part(part: str) -> bool:
    """Check if a part is an X-range indicator (x, X, *, etc.)."""
    return part.lower() in ('x', '*', '') or re.match(r'^[xX*]$', part)


def _parse_comparator_set(rng_str: str) -> List[Tuple[str, Version]]:
    """Parse a comparator set (whitespace-separated comparators that must all match)."""
    rng_str = rng_str.strip()
    if not rng_str or rng_str == '*':
        # Empty set or * matches any release
        return []

    comparators = []
    # Split by whitespace
    tokens = rng_str.split()

    i = 0
    while i < len(tokens):
        token = tokens[i]

        # Check for hyphen range: "1.2.3 - 2.3.4"
        if token == '-':
            if i + 2 >= len(tokens):
                raise ValueError(f"Invalid hyphen range: missing upper bound")
            lower_str = tokens[i - 1] if i > 0 else None
            # Actually, the hyphen is between two versions. Let's re-parse.
            # The format is "LOWER - UPPER" where LOWER and UPPER are version strings.
            # But we're parsing token by token. Let's handle this differently.
            raise ValueError(f"Hyphen ranges must be parsed as a unit")

        # Determine operator
        op = '='
        if token[0] in ('<', '>', '=', '!'):
            # Could be <, <=, >, >=, !=, =
            if len(token) >= 2 and token[1] in ('=', '!'):
                op = token[:2]
                ver_str = token[2:]
            else:
                op = token[0]
                ver_str = token[1:] if len(token) > 1 else ''
        else:
            ver_str = token

        # Handle tilde and caret prefixes
        if ver_str.startswith('~'):
            ver_str_no_tilde = ver_str[1:]
            if not ver_str_no_tilde:
                raise ValueError(f"Invalid tilde range: no version after ~")
            # Parse the version
            ver = _parse_partial_version(ver_str_no_tilde)
            comparators.append(('~', ver))
        elif ver_str.startswith('^'):
            ver_str_no_caret = ver_str[1:]
            if not ver_str_no_caret:
                raise ValueError(f"Invalid caret range: no version after ^")
            ver = _parse_partial_version(ver_str_no_caret)
            comparators.append(('^', ver))
        elif ver_str.startswith('!='):
            op = '!='
            ver_str = ver_str[2:]
            if not ver_str:
                raise ValueError(f"Invalid comparator: no version after !=")
            ver = _parse_partial_version(ver_str)
            comparators.append(('!=', ver))
        elif op in ('<', '>', '<=', '>=', '=') and ver_str:
            ver = _parse_partial_version(ver_str)
            comparators.append((op, ver))
        elif op == '=' and not ver_str:
            # Just "=" means exact match - but this is unusual. Treat as exact version?
            # Actually, in npm semver, "=" alone is invalid or treated as *
            raise ValueError(f"Invalid comparator: = without version")
        else:
            if ver_str:
                ver = _parse_partial_version(ver_str)
                comparators.append(('=', ver))
            else:
                raise ValueError(f"Invalid comparator token: {token}")

        i += 1

    return comparators


def _satisfies_single(version: Version, op: str, ref: Version) -> bool:
    """Check if version satisfies a single comparator with operator and reference version."""
    if op == '=':
        return version == ref
    elif op == '!=':
        return version != ref
    elif op == '<':
        return version < ref
    elif op == '<=':
        return version <= ref
    elif op == '>':
        return version > ref
    elif op == '>=':
        return version >= ref
    else:
        raise ValueError(f"Unknown operator: {op}")


def _satisfies_set(version: Version, comparators: List[Tuple[str, Version]]) -> bool:
    """Check if version satisfies a comparator set."""
    if not comparators:
        # Empty set matches any release
        return version.prerelease is None

    # Check prerelease rule: if the version has a prerelease, it only satisfies
    # if some comparator in the set has a version with the same MAJOR.MINOR.PATCH and a prerelease
    has_prerelease = version.prerelease is not None

    if has_prerelease:
        # Find if any comparator has a matching major.minor.patch with a prerelease
        can_satisfy = False
        for op, ref in comparators:
            # Check if ref has the same major.minor.patch and has a prerelease
            if (ref.major == version.major and
                ref.minor == version.minor and
                ref.patch == version.patch and
                ref.prerelease is not None):
                can_satisfy = True
                break

        if not can_satisfy:
            return False

    # Check all comparators
    for op, ref in comparators:
        if not _satisfies_single(version, op, ref):
            return False

    return True


def _expand_comparator_set(comparators: List[Tuple[str, Version]]) -> Optional[Tuple[Version, Version]]:
    """Expand a comparator set into a lower and upper bound (inclusive/exclusive).

    Returns (lower_inclusive, upper_exclusive) or None if the range is unbounded.
    This is used for efficient checking but we need to handle all cases.
    """
    # For simplicity, we'll just check against each comparator directly in satisfies_set
    pass


def satisfies(version: str, rng: str) -> bool:
    """Check if a version satisfies a range."""
    ver = parse(version)
    rng = rng.strip()

    # Split by ||
    sets_str = rng.split('||')
    for set_str in sets_str:
        comparators = _parse_comparator_set(set_str)
        if _satisfies_set(ver, comparators):
            return True
    return False


def max_satisfying(versions: List[str], rng: str) -> Optional[str]:
    """Return the highest version from the list that satisfies the range."""
    best = None
    best_str = None

    for v_str in versions:
        if satisfies(v_str, rng):
            ver = parse(v_str)
            if best is None or ver > best:
                best = ver
                best_str = v_str

    return best_str


if __name__ == '__main__':
    # Test cases
    print(parse("1.2.3"))
    print(parse("1.2.3-alpha.7"))
    print(parse("1.2.3+build.123"))
    print(parse("v1.2.3"))

    print(satisfies("1.2.3", ">=1.0.0"))
    print(satisfies("1.2.3", "<2.0.0"))
    print(satisfies("1.2.3-alpha", ">1.2.3-alpha.3"))
    print(satisfies("3.4.5-alpha.9", ">1.2.3-alpha.3"))  # Should be False

    print(max_satisfying(["1.0.0", "1.2.3", "2.0.0"], ">=1.0.0 <2.0.0"))
