    def expand_variables_in_text(text: str, env: dict[str, str], in_quotes: bool) -> str:
        """Expand variables in text. The in_quotes parameter affects behavior."""
        result = []
        i = 0
        while i < len(text):
            if text[i] == '$':
                if i + 1 >= len(text):
                    result.append('$')
                    i += 1
                elif text[i + 1] == '{':
                    j = find_closing_brace_pos(text, i + 2)
                    if j == -1:
                        raise ValueError("Unterminated ${")

                    inner = text[i + 2:j]
                    expanded_value = get_var_expansion(inner, env)
                    result.append(expanded_value)

                    i = j + 1
                elif text[i + 1].isalpha() or text[i + 1] == '_':
                    j = i + 2
                    while j < len(text) and (text[j].isalnum() or text[j] == '_'):
                        j += 1

                    var_name = text[i + 1:j]
                    expanded_value = env.get(var_name, '')
                    result.append(expanded_value)

                    i = j
                else:
                    result.append('$')
                    i += 1
            elif text[i] == '\\' and in_quotes:
                # In double quotes, handle backslash escapes
                if i + 1 >= len(text):
                    raise ValueError("Trailing backslash")
                next_ch = text[i + 1]
                if next_ch in ('$', '"', '\\', '\n'):
                    if next_ch == '\n':
                        # Backslash-newline removed
                        i += 2
                        continue
                    else:
                        result.append(next_ch)
                        i += 2
                else:
                    result.append('\\')
                    i += 1
            elif text[i] == '\\' and not in_quotes:
                # Unquoted backslash
                if i + 1 >= len(text):
                    raise ValueError("Trailing backslash")
                next_ch = text[i + 1]
                if next_ch == '\n':
                    # Backslash-newline removed entirely
                    i += 2
                else:
                    result.append(next_ch)
                    i += 2
            else:
                result.append(text[i])
                i += 1

        return ''.join(result)

    def find_closing_brace_pos(text: str, start: int) -> int:
        """Find closing } for ${ starting search at position start."""
        depth = 1
        i = start
        while i < len(text):
            if text[i] == '{':
                depth += 1
            elif text[i] == '}':
                depth -= 1
                if depth == 0:
                    return i
            i += 1
        return -1

    def get_var_expansion(inner: str, env: dict[str, str]) -> str:
        """Expand ${...} content."""
        # Parse variable name
        i = 0
        if not (inner[i].isalpha() or inner[i] == '_'):
            raise ValueError(f"Invalid variable name in ${inner}")

        j = i + 1
        while j < len(inner) and (inner[j].isalnum() or inner[j] == '_'):
            j += 1

        var_name = inner[i:j]

        if j >= len(inner):
            return env.get(var_name, '')

        if inner[j] == ':':
            if j + 1 >= len(inner) or inner[j + 1] != '-':
                raise ValueError(f"Invalid syntax in ${inner}")

            default_start = j + 2
            default_text = extract_default_content(inner, default_start)
            expanded_default = expand_variables_in_text(default_text, env, True)

            current_value = env.get(var_name, None)
            if current_value is None or current_value == '':
                return expanded_default
            else:
                return current_value
        elif inner[j] == '-':
            default_start = j + 1
            default_text = extract_default_content(inner, default_start)
            expanded_default = expand_variables_in_text(default_text, env, True)

            if var_name not in env:
                return expanded_default
            else:
                return env[var_name]
        else:
            return env.get(var_name, '')

    def extract_default_content(inner: str, start: int) -> str:
        """Extract default value text from inner string."""
        result = []
        i = start
        depth = 0
        while i < len(inner):
            if inner[i] == '{':
                depth += 1
                result.append('{')
            elif inner[i] == '}':
                if depth == 0:
                    break
                depth -= 1
                result.append('}')
            else:
                result.append(inner[i])
            i += 1
        return ''.join(result)

    # Main parsing: build words with tracking of quoted/unquoted expansions
    words = []
    current_word_builder = WordBuilder()
    i = 0

    while i < len(line):
        ch = line[i]

        if ch == "'":
            # Single-quoted: literal until next '
            i += 1
            start = i
            while i < len(line) and line[i] != "'":
                i += 1
            if i >= len(line):
                raise ValueError("Unterminated single quote")

            content = line[start:i]
            current_word_builder.add_literal(content, quoted=True)
            i += 1

        elif ch == '"':
            # Double-quoted
            i += 1
            parts_result = []
            while i < len(line) and line[i] != '"':
                if line[i] == '$':
                    if i + 1 >= len(line):
                        parts_result.append(('$', False, True))  # literal $, was in quotes
                        i += 1
                    elif line[i + 1] == '{':
                        j = find_closing_brace_pos(line, i + 2)
                        if j == -1:
                            raise ValueError("Unterminated ${")

                        inner = line[i + 2:j]
                        expanded = get_var_expansion(inner, env)
                        parts_result.append((expanded, False, True))  # expanded value, quoted context
                        i = j + 1
                    elif line[i + 1].isalpha() or line[i + 1] == '_':
                        j = i + 2
                        while j < len(line) and (line[j].isalnum() or line[j] == '_'):
                            j += 1

                        var_name = line[i + 1:j]
                        expanded = env.get(var_name, '')
                        parts_result.append((expanded, False, True))
                        i = j
                    else:
                        parts_result.append(('$', False, True))
                        i += 1
                elif line[i] == '\\':
                    if i + 1 >= len(line):
                        raise ValueError("Trailing backslash")
                    next_ch = line[i + 1]
                    if next_ch in ('$', '"', '\\', '\n'):
                        if next_ch == '\n':
                            i += 2
                            continue
                        else:
                            parts_result.append((next_ch, False, True))
                            i += 2
                    else:
                        parts_result.append(('\\\\', False, True))  # literal backslash
                        i += 1
                else:
                    parts_result.append((line[i], False, True))
                    i += 1

            if i >= len(line):
                raise ValueError("Unterminated double quote")

            # Join all parts
            joined = ''.join(p[0] for p in parts_result)
            current_word_builder.add_literal(joined, quoted=True)
            i += 1

        elif ch in (' ', '\t', '\n'):
            # Whitespace: end current word if any
            if current_word_builder.has_content():
                word_str = current_word_builder.to_string()
                is_entirely_unquoted_expansion_empty = current_word_builder.is_entirely_unquoted_expansion_and_empty()

                if current_word_builder.was_fully_quoted():
                    words.append(word_str)
                else:
                    # Split on whitespace
                    split_parts = word_str.split()
                    words.extend(split_parts)

                current_word_builder = WordBuilder()

            i += 1

        elif ch == '\\':
            # Unquoted backslash
            if i + 1 >= len(line):
                raise ValueError("Trailing backslash")

            next_ch = line[i + 1]
            if next_ch == '\n':
                # Backslash-newline removed
                i += 2
            else:
                current_word_builder.add_literal(next_ch, quoted=False)
                i += 2

        else:
            current_word_builder.add_literal(ch, quoted=False)
            i += 1

    # Handle remaining content
    if current_word_builder.has_content():
        word_str = current_word_builder.to_string()

        if current_word_builder.was_fully_quoted():
            words.append(word_str)
        else:
            split_parts = word_str.split()
            words.extend(split_parts)

    return words


class WordBuilder:
    """Helper class to build a word from parts, tracking quoting context."""

    def __init__(self):
        self.parts = []  # List of (text, quoted: bool)

    def add_literal(self, text: str, quoted: bool):
        self.parts.append((text, quoted))

    def has_content(self) -> bool:
        return len(self.parts) > 0

    def to_string(self) -> str:
        return ''.join(text for text, _ in self.parts)

    def was_fully_quoted(self) -> bool:
        """Check if all parts were quoted."""
        return all(quoted for _, quoted in self.parts)

    def is_entirely_unquoted_expansion_and_empty(self) -> bool:
        """
        Check if the word consists entirely of unquoted expansions that resulted in empty strings.
        This is used to remove such words per POSIX spec.

        For simplicity, we track if the word was built from unquoted context and check if result is empty.
        Actually, the rule is more nuanced: only remove if it's ENTIRELY an unquoted expansion that became empty.
        A literal empty string like "" or '' should NOT be removed.

        For this implementation, since we're joining parts, if the entire word came from unquoted context
        and the result is empty, we remove it. But if any part was quoted (even if empty), we keep it.
        """
        # If all parts were quoted, don't remove even if empty
        if self.was_fully_quoted():
            return False

        # If the result is not empty, don't remove
        word_str = self.to_string()
        if word_str:
            return False

        # Result is empty and not fully quoted - check if it was from unquoted expansions
        # In our simplified model, if it's not fully quoted and empty, remove it
        return True
