def split_command(line: str, env: dict[str, str]) -> list[str]:
    """
    Implement a subset of POSIX shell word splitting and parameter expansion.

    Args:
        line: The command line string to parse.
        env: The environment variables for expansion.

    Returns:
        A list of words after parsing, expanding, and splitting.

    Raises:
        ValueError: For unterminated quotes, unterminated ${}, or trailing backslash.
    """

    def find_closing_brace_pos(text: str, start: int) -> int:
        """Find closing } for ${ starting search at position start."""
        depth = 1
        i = start
        while i < len(text):
            if text[i] == '{':
                depth += 1
            elif text[i] == '}':
                depth -= 1
                if depth == 0:
                    return i
            i += 1
        return -1

    def get_var_expansion(inner: str, env: dict[str, str]) -> str:
        """Expand ${...} content."""
        # Parse variable name
        i = 0
        if not (inner[i].isalpha() or inner[i] == '_'):
            raise ValueError(f"Invalid variable name in ${{{inner}}}")

        j = i + 1
        while j < len(inner) and (inner[j].isalnum() or inner[j] == '_'):
            j += 1

        var_name = inner[i:j]

        if j >= len(inner):
            return env.get(var_name, '')

        if inner[j] == ':':
            if j + 1 >= len(inner) or inner[j + 1] != '-':
                raise ValueError(f"Invalid syntax in ${{{inner}}}")

            default_start = j + 2
            default_text = extract_default_content(inner, default_start)
            expanded_default = expand_vars_simple(default_text, env)

            current_value = env.get(var_name, None)
            if current_value is None or current_value == '':
                return expanded_default
            else:
                return current_value
        elif inner[j] == '-':
            default_start = j + 1
            default_text = extract_default_content(inner, default_start)
            expanded_default = expand_vars_simple(default_text, env)

            if var_name not in env:
                return expanded_default
            else:
                return env[var_name]
        else:
            return env.get(var_name, '')

    def extract_default_content(inner: str, start: int) -> str:
        """Extract default value text from inner string."""
        result = []
        i = start
        depth = 0
        while i < len(inner):
            if inner[i] == '{':
                depth += 1
                result.append('{')
            elif inner[i] == '}':
                if depth == 0:
                    break
                depth -= 1
                result.append('}')
            else:
                result.append(inner[i])
            i += 1
        return ''.join(result)

    def expand_vars_simple(text: str, env: dict[str, str]) -> str:
        """Simple variable expansion without quote handling (for defaults inside ${})."""
        result = []
        i = 0
        while i < len(text):
            if text[i] == '$':
                if i + 1 >= len(text):
                    result.append('$')
                    i += 1
                elif text[i + 1] == '{':
                    j = find_closing_brace_pos(text, i + 2)
                    if j == -1:
                        raise ValueError("Unterminated ${")

                    inner = text[i + 2:j]
                    expanded_value = get_var_expansion(inner, env)
                    result.append(expanded_value)

                    i = j + 1
                elif text[i + 1].isalpha() or text[i + 1] == '_':
                    j = i + 2
                    while j < len(text) and (text[j].isalnum() or text[j] == '_'):
                        j += 1

                    var_name = text[i + 1:j]
                    expanded_value = env.get(var_name, '')
                    result.append(expanded_value)

                    i = j
                else:
                    result.append('$')
                    i += 1
            else:
                result.append(text[i])
                i += 1

        return ''.join(result)

    # Main parsing
    words = []
    current_word_parts = []  # List of (text, was_quoted_expansion: bool)
    # was_quoted_expansion tracks if the text came from a quoted context where expansion happened
    # For literal text in quotes, it's "quoted" but not an "expansion"

    i = 0

    while i < len(line):
        ch = line[i]

        if ch == "'":
            # Single-quoted: literal until next '
            i += 1
            start = i
            while i < len(line) and line[i] != "'":
                i += 1
            if i >= len(line):
                raise ValueError("Unterminated single quote")

            content = line[start:i]
            current_word_parts.append((content, False))  # quoted literal, not an expansion
            i += 1

        elif ch == '"':
            # Double-quoted: handle escapes and $ expansion
            i += 1
            parts_result = []
            while i < len(line) and line[i] != '"':
                if line[i] == '$':
                    if i + 1 >= len(line):
                        parts_result.append(('$', True))  # literal $, was in quoted context
                        i += 1
                    elif line[i + 1] == '{':
                        j = find_closing_brace_pos(line, i + 2)
                        if j == -1:
                            raise ValueError("Unterminated ${")

                        inner = line[i + 2:j]
                        expanded = get_var_expansion(inner, env)
                        parts_result.append((expanded, True))  # expansion in quoted context
                        i = j + 1
                    elif line[i + 1].isalpha() or line[i + 1] == '_':
                        j = i + 2
                        while j < len(line) and (line[j].isalnum() or line[j] == '_'):
                            j += 1

                        var_name = line[i + 1:j]
                        expanded = env.get(var_name, '')
                        parts_result.append((expanded, True))
                        i = j
                    else:
                        parts_result.append(('$', True))
                        i += 1
                elif line[i] == '\\':
                    if i + 1 >= len(line):
                        raise ValueError("Trailing backslash")
                    next_ch = line[i + 1]
                    if next_ch in ('$', '"', '\\', '\n'):
                        if next_ch == '\n':
                            i += 2
                            continue
                        else:
                            parts_result.append((next_ch, True))
                            i += 2
                    else:
                        # Other backslashes stay as is
                        parts_result.append(('\\\\', True))
                        i += 1
                else:
                    parts_result.append((line[i], True))
                    i += 1

            if i >= len(line):
                raise ValueError("Unterminated double quote")

            # Join all parts into one string, marked as quoted context
            joined = ''.join(p[0] for p in parts_result)
            current_word_parts.append((joined, True))  # all from quoted context
            i += 1

        elif ch in (' ', '\t', '\n'):
            # Whitespace: end current word if any
            if current_word_parts:
                word_str = ''.join(text for text, _ in current_word_parts)

                # Check if the word was entirely from quoted context
                all_quoted = all(quoted for _, quoted in current_word_parts)

                if all_quoted:
                    words.append(word_str)
                else:
                    # Split on whitespace (field splitting for unquoted parts)
                    split_parts = word_str.split()
                    words.extend(split_parts)

                current_word_parts = []

            i += 1

        elif ch == '\\':
            # Unquoted backslash
            if i + 1 >= len(line):
                raise ValueError("Trailing backslash")

            next_ch = line[i + 1]
            if next_ch == '\n':
                # Backslash-newline removed entirely
                i += 2
            else:
                current_word_parts.append((next_ch, False))  # unquoted literal
                i += 2

        else:
            current_word_parts.append((ch, False))  # unquoted literal
            i += 1

    # Handle remaining content
    if current_word_parts:
        word_str = ''.join(text for text, _ in current_word_parts)

        all_quoted = all(quoted for _, quoted in current_word_parts)

        if all_quoted:
            words.append(word_str)
        else:
            split_parts = word_str.split()
            words.extend(split_parts)

    return words
