from __future__ import annotations

import dataclasses
import typing
from typing import (
    Any,
    Dict,
    List,
    Optional,
    Tuple,
    Union,
    get_type_hints,
    get_origin,
    get_args,
)

try:
    from types import UnionType  # Python 3.10+
except ImportError:
    UnionType = None


class LoadError(ValueError):
    """Error raised when loading data fails."""

    def __init__(self, path: str, message: str):
        self.path = path
        self.message = message
        super().__init__(f"{path}: {message}")

    def __str__(self):
        return f"{self.path}: {self.message}"


def _is_union_type(tp: Any) -> bool:
    """Check if tp is a Union type (including `X | Y` syntax)."""
    origin = get_origin(tp)
    if origin is Union:
        return True
    if UnionType is not None and isinstance(tp, UnionType):
        return True
    return False


def _get_union_members(tp: Any) -> List[Any]:
    """Get the member types of a Union."""
    origin = get_origin(tp)
    if origin is Union:
        return list(get_args(tp))
    if UnionType is not None and isinstance(tp, UnionType):
        # For Python 3.10+ union types, we need to extract members differently
        args = getattr(tp, '__args__', ())
        return list(args)
    return []


def _is_optional(tp: Any) -> bool:
    """Check if tp is Optional[T] (i.e., Union[T, None])."""
    if not _is_union_type(tp):
        return False
    members = _get_union_members(tp)
    non_none = [m for m in members if m is not type(None)]
    has_none = type(None) in members
    return has_none and len(non_none) == 1


def _get_optional_inner(tp: Any) -> Any:
    """Get the inner type T from Optional[T]."""
    members = _get_union_members(tp)
    for m in members:
        if m is not type(None):
            return m
    raise ValueError("Optional without inner type")


def _is_literal(tp: Any) -> bool:
    """Check if tp is Literal[...]."""
    return get_origin(tp) is typing.Literal


def _get_literal_values(tp: Any) -> List[Any]:
    """Get the literal values from Literal[...]."""
    return list(get_args(tp))


def _is_list(tp: Any) -> bool:
    """Check if tp is list[T] or List[T]."""
    origin = get_origin(tp)
    return origin is list or (hasattr(typing, 'List') and origin is typing.List)


def _get_list_element_type(tp: Any) -> Any:
    """Get the element type T from list[T]."""
    args = get_args(tp)
    if args:
        return args[0]
    raise ValueError("list without type argument")


def _is_dict(tp: Any) -> bool:
    """Check if tp is dict[str, T] or Dict[str, T]."""
    origin = get_origin(tp)
    return origin is dict or (hasattr(typing, 'Dict') and origin is typing.Dict)


def _get_dict_key_type(tp: Any) -> Any:
    """Get the key type from dict[K, V]."""
    args = get_args(tp)
    if len(args) >= 1:
        return args[0]
    raise ValueError("dict without key type")


def _get_dict_value_type(tp: Any) -> Any:
    """Get the value type T from dict[str, T]."""
    args = get_args(tp)
    if len(args) >= 2:
        return args[1]
    raise ValueError("dict without value type")


def _is_tuple(tp: Any) -> bool:
    """Check if tp is tuple[T, ...] or tuple[A, B, C]."""
    origin = get_origin(tp)
    return origin is tuple or (hasattr(typing, 'Tuple') and origin is typing.Tuple)


def _get_tuple_element_types(tp: Any) -> List[Any]:
    """Get the element types from tuple[T, ...] or tuple[A, B, C]."""
    args = get_args(tp)
    if not args:
        return []
    # Check for variadic tuple: tuple[T, ...]
    if len(args) == 2 and args[1] is Ellipsis:
        return [args[0]]
    return list(args)


def _is_dataclass(tp: Any) -> bool:
    """Check if tp is a dataclass type."""
    return dataclasses.is_dataclass(tp)


def load(cls: type, data: Any, path: str = "$") -> Any:
    """Load an instance of cls from JSON-like data, validating types."""

    # Resolve string annotations
    try:
        hints = get_type_hints(cls)
    except Exception:
        hints = {}

    # Get the annotation for this class if it's not a primitive type
    # For the top-level call, cls is the target type.
    # We need to determine what type we're loading into.

    return _load_with_type(cls, data, path, hints)


def _load_with_type(tp: Any, data: Any, path: str, hints: Dict[str, Any] | None = None) -> Any:
    """Load data according to the type tp."""

    # Handle None type
    if tp is type(None):
        if data is None:
            return None
        raise LoadError(path, f"expected None, got {type(data).__name__}")

    # Handle Literal types
    if _is_literal(tp):
        literal_values = _get_literal_values(tp)
        # Check if the value matches one of the literal values AND has the correct type
        for lv in literal_values:
            if data == lv and type(data) is type(lv):
                return data
        raise LoadError(path, f"expected one of {literal_values}, got {repr(data)}")

    # Handle Union types (including Optional)
    if _is_union_type(tp):
        members = _get_union_members(tp)
        # Try each member left to right
        errors = []
        for member in members:
            try:
                return _load_with_type(member, data, path, hints)
            except LoadError as e:
                errors.append(e)
            except Exception as e:
                errors.append(LoadError(path, f"error loading {member}: {e}"))

        # If None is in the members and data is None, return None
        if type(None) in members and data is None:
            return None

        # All members failed - raise an error for the first member that tried to load non-None data
        # But we need to be careful with Optional: if data is not None, report the error from loading T
        # If all members rejected it (including None rejecting non-None), report appropriately
        if len(errors) > 0:
            # For unions, we want to show the error from trying to load as the first type that didn't reject early
            # Actually, per spec: "For T | None with non-null data, report the error from loading T"
            # Let's find the first non-None member and use its error if it loaded something but failed deep
            # If all members gave LoadErrors, we need to decide which path to show

            # Special handling for Optional: if one member is None and others failed
            non_none_members = [m for m in members if m is not type(None)]
            if len(non_none_members) == 1 and data is not None:
                # This is like Optional[T], report the error from loading T
                raise errors[0]  # The first non-None member's error should be relevant

            # For general unions, raise the first error
            raise errors[0]

        raise LoadError(path, f"no union member matched for {repr(data)}")

    # Handle primitive types
    if tp is int:
        if isinstance(data, bool):
            raise LoadError(path, f"expected int, got bool (bool is not accepted for int)")
        if isinstance(data, int):
            return data
        raise LoadError(path, f"expected int, got {type(data).__name__}")

    if tp is float:
        if isinstance(data, bool):
            raise LoadError(path, f"expected float, got bool (bool is not accepted for float)")
        if isinstance(data, (int, float)):
            return float(data)
        raise LoadError(path, f"expected float, got {type(data).__name__}")

    if tp is str:
        if isinstance(data, str):
            return data
        raise LoadError(path, f"expected str, got {type(data).__name__}")

    if tp is bool:
        if isinstance(data, bool):
            return data
        raise LoadError(path, f"expected bool, got {type(data).__name__}")

    # Handle list types
    if _is_list(tp):
        if not isinstance(data, list):
            raise LoadError(path, f"expected list, got {type(data).__name__}")
        elem_type = _get_list_element_type(tp)
