        line = tolower($0)
        # Replace non-word characters (not letters, digits, apostrophes) with spaces
        gsub(/[^a-z0-9'\''']/, " ", line)
        # Split into words
        split(line, words, / +/)
        for (i in words) {
            w = words[i]
            if (w == "") continue

            # Strip leading apostrophes
            while (substr(w, 1, 1) == "'\''") {
                w = substr(w, 2)
            }
            # Strip trailing apostrophes
            while (length(w) > 0 && substr(w, length(w), 1) == "'\''") {
                w = substr(w, 1, length(w) - 1)
            }

            if (w == "") continue

            count[w]++
        }
