    END {
        # Collect all words into an array for sorting
        num_words = 0
        for (w in count) {
            num_words++
            word_list[num_words] = w
            count_list[num_words] = count[w]
        }

        # Sort by count descending, then word ascending (byte order / LC_ALL=C)
        # Simple insertion sort since awk does not have built-in sort in POSIX
        for (i = 2; i <= num_words; i++) {
            key_w = word_list[i]
            key_c = count_list[i]
            j = i - 1
            while (j >= 1 && (count_list[j] < key_c || (count_list[j] == key_c && word_list[j] > key_w))) {
                word_list[j+1] = word_list[j]
                count_list[j+1] = count_list[j]
                j--
            }
            word_list[j+1] = key_w
            count_list[j+1] = key_c
        }

